import java.util.*;

public class Main {
    int evalRPN(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        Set<String> ops = Set.of("+", "-", "*", "/");
        for (String t : tokens) {
            if (ops.contains(t)) {
                int b = stack.pop();                                                // the SECOND popped operand is the RIGHT-hand side
                int a = stack.pop();                                                // the FIRST popped operand is the LEFT-hand side
                switch (t) {
                    case "+": stack.push(a + b); break;
                    case "-": stack.push(a - b); break;
                    case "*": stack.push(a * b); break;
                    default: stack.push(a / b);                                        // Java's integer division already truncates toward zero
                }
            } else {
                stack.push(Integer.parseInt(t));
            }
        }
        return stack.peek();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] tokens = {"2", "1", "+", "3", "*"};
        System.out.println(solution.evalRPN(tokens));
    }
}

