#include <bits/stdc++.h>
using namespace std;

int evalRPN(vector<string>& tokens) {
    vector<int> stack;
    unordered_set<string> ops = {"+", "-", "*", "/"};
    for (const string& t : tokens) {
        if (ops.count(t)) {
            int b = stack.back(); stack.pop_back();                                 // the SECOND popped operand is the RIGHT-hand side
            int a = stack.back(); stack.pop_back();                                 // the FIRST popped operand is the LEFT-hand side
            if (t == "+") stack.push_back(a + b);
            else if (t == "-") stack.push_back(a - b);
            else if (t == "*") stack.push_back(a * b);
            else stack.push_back(a / b);                                              // C++'s integer division already truncates toward zero
        } else {
            stack.push_back(stoi(t));
        }
    }
    return stack.back();
}

int main() {
    vector<string> tokens = {"2", "1", "+", "3", "*"};
    cout << evalRPN(tokens) << endl;
    return 0;
}

